const vertexShader="precision highp float;\n\nattribute vec3 position;\nattribute vec2 uv;\n\nuniform mat4 modelViewMatrix;\nuniform mat4 projectionMatrix;\n\nvarying vec2 v_uv;\n\nvoid main() {\n\tv_uv = uv;\n\n\tgl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);\n}\n";
const fragmentShader="precision highp float;\n\nuniform sampler2D u_texture1;\nuniform sampler2D u_texture2;\nuniform vec2 u_meshSize;\nuniform vec2 u_textureSize1;\nuniform vec2 u_textureSize2;\nuniform vec2 u_mouse;\nuniform float u_squareSize;\nuniform float u_lensDistortion;\nuniform float u_rgbShiftR;\nuniform float u_rgbShiftG;\nuniform float u_rgbShiftB;\nuniform float u_waveFrequency;\nuniform float u_waveStrength;\nuniform float u_waveSpeed;\nuniform float u_randomFrequency;\nuniform float u_randomStrength;\nuniform float u_randomSpeed;\nuniform float u_time;\n\nvarying vec2 v_uv;\n\n// ---------------------------------------------------------------------------\n// Make the texture UVs behave like CSS's `background-size: cover`.\n// ---------------------------------------------------------------------------\nvec2 getCoverUv(vec2 uv, vec2 meshSize, vec2 textureSize) {\n  vec2 meshRatio = vec2(meshSize.x / meshSize.y, meshSize.y / meshSize.x);\n  vec2 textureRatio = vec2(textureSize.x / textureSize.y, textureSize.y / textureSize.x);\n  vec2 resolutionRatio = vec2(\n    min(meshRatio.x / textureRatio.x, 1.0),\n    min(meshRatio.y / textureRatio.y, 1.0)\n  );\n\n  return (uv - 0.5) * resolutionRatio + 0.5;\n}\n\n// ---------------------------------------------------------------------------\n// Applies a CC Lens-style radial distortion to UV coordinates.\n// ---------------------------------------------------------------------------\nfloat getCCLensScale(float distortion, float radius2) {\n  if (distortion >= 0.0) {\n    return 1.0 + distortion * radius2;\n  }\n\n  return 1.0 / (1.0 - distortion * radius2);\n}\n\nvec2 getCCLensUv(vec2 uv, vec2 resolution, float distortion) {\n  vec2 centeredUv = uv - 0.5;\n  vec2 aspectScale = vec2(resolution.x / resolution.y, 1.0);\n  vec2 centeredPosition = centeredUv * aspectScale;\n\n  float radius2 = dot(centeredPosition, centeredPosition);\n  float lensScale = getCCLensScale(distortion, radius2);\n\n  vec2 distortedPosition = centeredPosition * lensScale;\n  vec2 distortedCenteredUv = distortedPosition / aspectScale;\n  vec2 distortedUv = distortedCenteredUv + 0.5;\n  vec2 distortionOffset = distortedUv - uv;\n\n  return uv - distortionOffset;\n}\n\n// ---------------------------------------------------------------------------\n// Generates a pseudo-random vec3 from a 3D input coordinate.\n// ---------------------------------------------------------------------------\n// <www.shadertoy.com/view/XsX3zB>\n// by Nikita Miropolskiy\nvec3 random3(vec3 c) {\n  float j = 4096.0 * sin(dot(c, vec3(17.0, 59.4, 15.0)));\n  vec3 r;\n\n  r.z = fract(512.0 * j);\n  j *= 0.125;\n  r.x = fract(512.0 * j);\n  j *= 0.125;\n  r.y = fract(512.0 * j);\n\n  return r - 0.5;\n}\n\n\nvoid main() {\n  vec2 imageUv = (v_uv - 0.5) * 1.2 + 0.5;\n  vec2 texture2Uv = getCoverUv(imageUv, u_meshSize, u_textureSize2);\n\n  // Convert the square UV coordinates from the 0.0-to-1.0 range to the -1.0-to-1.0 range.\n  vec2 uvSquare = imageUv * 2.0 - 1.0;\n\n  // Offset the coordinates so the mouse position becomes the origin for the square test.\n  uvSquare -= u_mouse;\n\n  // Calculate an aspect-ratio correction factor for determining the square's bounds.\n  vec2 squareAspectScale = vec2(min((u_meshSize.y / u_meshSize.x), 1.0), min((u_meshSize.x / u_meshSize.y), 1.0));\n\n  // Correct the test coordinates so the mask remains square.\n  uvSquare /= squareAspectScale;\n\n  float wave = sin(\n    texture2Uv.y * u_waveFrequency\n    + u_time * u_waveSpeed\n  ) * u_waveStrength;\n  texture2Uv.y += wave;\n  texture2Uv += random3(\n    vec3(texture2Uv * u_randomFrequency, u_time * u_randomSpeed)\n  ).x * u_randomStrength;\n\n  // Store half the square's side length so u_squareSize can control its size.\n  float squareHalfSize = u_squareSize;\n\n  // Calculate the square's left edge.\n  float left = -squareHalfSize;\n\n  // Calculate the square's right edge.\n  float right = squareHalfSize;\n\n  // Calculate the square's bottom edge.\n  float bottom = -squareHalfSize;\n\n  // Calculate the square's top edge.\n  float top = squareHalfSize;\n\n  // Return 1.0 when uvSquare is inside the square and 0.0 when it is outside.\n  float squareMask = step(left, uvSquare.x) * (1.0 - step(right, uvSquare.x)) * step(bottom, uvSquare.y) * (1.0 - step(top, uvSquare.y));\n\n  // Convert uvSquare to the 0.0-to-1.0 range for the CC Lens distortion.\n  vec2 squareUv = uvSquare / (squareHalfSize * 2.0) + 0.5;\n\n  // Apply the CC Lens distortion inside the square.\n  vec2 distortedSquareUv = getCCLensUv(squareUv, vec2(1.0), u_lensDistortion);\n\n  // Calculate the square-local offset from the difference before and after distortion.\n  vec2 squareLensOffset = distortedSquareUv - squareUv;\n\n  // squareLensOffset is relative to the square. Adding it directly to imageUv would treat it as\n  // relative to the entire mesh and make the distortion too large, so scale it by the square's\n  // half-size and aspect-ratio correction factor to convert it to a mesh-relative offset.\n  vec2 viewportLensOffset = squareLensOffset * squareHalfSize * squareAspectScale;\n\n  // Convert the coordinates inside the square to UV coordinates for u_texture1.\n  vec2 lensTexture1Uv = getCoverUv(imageUv + viewportLensOffset, u_meshSize, u_textureSize1);\n\n  // Use the square's center as the origin so the RGB shift grows stronger toward the outside.\n  vec2 rgbShiftDirection = (squareUv - 0.5) * 2.0;\n\n  // Sample each RGB channel with a different UV offset to create color separation.\n  float r = texture2D(u_texture1, lensTexture1Uv + rgbShiftDirection * u_rgbShiftR).r;\n  float g = texture2D(u_texture1, lensTexture1Uv + rgbShiftDirection * u_rgbShiftG).g;\n  float b = texture2D(u_texture1, lensTexture1Uv + rgbShiftDirection * u_rgbShiftB).b;\n\n  // Recombine the shifted u_texture1 channels to create the color inside the square.\n  vec4 insideColor = vec4(r, g, b, 1.0);\n\n  // Sample u_texture2 for the color outside the square.\n  vec4 outsideColor = texture2D(u_texture2, texture2Uv);\n\n  // Blend the inside and outside colors according to the square mask.\n  vec4 finalColor = mix(outsideColor, insideColor, squareMask);\n\n  gl_FragColor = finalColor;\n}\n";

// Integration only: original GLSL and constructor defaults; reuse the site's Three.js.
// The supplied transparent image is composited over gray, then duplicated in grayscale.
(() => {
 const root=document.getElementById('loader'),canvas=document.getElementById('cover-lens');
 const params={squareSize:.4,lensDistortion:.35,rgbShiftR:.0015,rgbShiftG:0,rgbShiftB:-.0015,waveFrequency:10,waveStrength:.0015,waveSpeed:1,randomFrequency:1,randomStrength:.001,randomSpeed:.2,pointerEase:.1};
 Object.assign(params,window.__presentationSettings?.cover||{});
 const controls=[['squareSize','Square size',0,5,.01],['lensDistortion','Lens distortion',-5,5,.01],['rgbShiftR','Red shift',-.05,.05,.001],['rgbShiftG','Green shift',-.05,.05,.001],['rgbShiftB','Blue shift',-.05,.05,.001],['waveFrequency','Wave frequency',0,200,1],['waveStrength','Wave strength',0,.1,.001],['waveSpeed','Wave speed',0,5,.01],['randomFrequency','Random frequency',.1,20,.1],['randomStrength','Random strength',0,.1,.001],['randomSpeed','Random speed',0,2,.01],['pointerEase','Pointer ease',.01,1,.01]];
 const panel=document.createElement('details');panel.id='cover-controls';panel.innerHTML='<summary>Lens controls</summary>'+controls.map(([key,label,min,max,step])=>'<label>'+label+'<output id="cover-'+key+'-value">'+params[key]+'</output><input aria-label="'+label+'" id="cover-'+key+'" type="range" min="'+min+'" max="'+max+'" step="'+step+'" value="'+params[key]+'"></label>').join('');root.append(panel);
 const renderer=new THREE.WebGLRenderer({canvas,alpha:true}),scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(45,1,.01,10000);
 renderer.setClearColor(0xffffff,0);renderer.setPixelRatio(Math.min(devicePixelRatio,2));
 const mouse=new THREE.Vector2(),mouseEase=new THREE.Vector2(),uniforms={u_texture1:{value:null},u_texture2:{value:null},u_meshSize:{value:new THREE.Vector2(1,1)},u_textureSize1:{value:new THREE.Vector2(1,1)},u_textureSize2:{value:new THREE.Vector2(1,1)},u_mouse:{value:new THREE.Vector2()},u_time:{value:0}};
 for(const [key,value]of Object.entries(params))if(key!=='pointerEase')uniforms['u_'+key]={value};
 const geometry=new THREE.PlaneGeometry(),material=new THREE.RawShaderMaterial({vertexShader,fragmentShader,uniforms}),mesh=new THREE.Mesh(geometry,material);scene.add(mesh);
 let active=false,raf=0,loaded=false;
 function resize(){const width=innerWidth,height=innerHeight;camera.aspect=width/height;camera.updateProjectionMatrix();camera.position.z=height/(2*Math.tan(camera.fov*Math.PI/360));renderer.setSize(width,height);mesh.scale.set(width*1.2,height*1.2,1);mesh.position.y=-height*.03;uniforms.u_meshSize.value.set(width,height);}
 function pointer(event){mouse.set(event.clientX/innerWidth*2-1,-(event.clientY/innerHeight-.53)*2);canvas.dataset.target=mouse.toArray().join(',');}
 function frame(){if(!active)return;raf=requestAnimationFrame(frame);if(!loaded||document.hidden)return;mouseEase.lerp(mouse,params.pointerEase);uniforms.u_mouse.value.copy(mouseEase);uniforms.u_time.value=performance.now()*.001;renderer.render(scene,camera);window.entryGlass?.renderBackdrop(canvas);canvas.dataset.pointer=mouseEase.toArray().map(n=>n.toFixed(4)).join(',');}
 for(const [key]of controls)panel.querySelector('#cover-'+key).addEventListener('input',event=>{params[key]=Number(event.target.value);panel.querySelector('#cover-'+key+'-value').textContent=params[key];if(key!=='pointerEase')uniforms['u_'+key].value=params[key];});
 addEventListener('pointermove',pointer);addEventListener('resize',resize);resize();
 const ready=(async()=>{
  const image=new Image();image.src="data:image/png;base64,";await image.decode();
  const colour=document.createElement('canvas');colour.width=image.naturalWidth;colour.height=image.naturalHeight;const ctx=colour.getContext('2d');ctx.fillStyle='#d9d9d9';ctx.fillRect(0,0,colour.width,colour.height);ctx.drawImage(image,0,0);
  const gray=document.createElement('canvas');gray.width=colour.width;gray.height=colour.height;const grayCtx=gray.getContext('2d');grayCtx.filter='grayscale(1)';grayCtx.drawImage(colour,0,0);
  const texture1=new THREE.CanvasTexture(colour),texture2=new THREE.CanvasTexture(gray);uniforms.u_texture1.value=texture1;uniforms.u_texture2.value=texture2;uniforms.u_textureSize1.value.set(colour.width,colour.height);uniforms.u_textureSize2.value.set(gray.width,gray.height);
  renderer.initTexture(texture1);renderer.initTexture(texture2);renderer.compile(scene,camera);loaded=true;renderer.render(scene,camera);canvas.dataset.ready='true';canvas.dataset.source='Mouse Following Square Lens Effect — original GLSL';
 })();
 // The main loader awaits this promise as well as its existing model/texture preparation.
 ready.catch(error=>{canvas.dataset.error=error.message;});
 function stop(){if(!active)return;active=false;cancelAnimationFrame(raf);removeEventListener('pointermove',pointer);removeEventListener('resize',resize);geometry.dispose();material.dispose();uniforms.u_texture1.value?.dispose();uniforms.u_texture2.value?.dispose();uniforms.u_texture1.value=uniforms.u_texture2.value=null;renderer.dispose();renderer.forceContextLoss();}
 function start(){if(active)return;root.classList.remove('cover-loading');active=true;frame();}
 window.coverLens={ready,start,stop,get active(){return active;}};
})();
